import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useNavigate } from 'react-router-dom'
import { useProgressStore } from '../stores/progressStore'
import { useAuthStore } from '../stores/authStore'
import { useUIText } from '../utils/uiText'

const ProgressPage: React.FC = () => {
  const navigate = useNavigate()
  const {
    streak,
    totalXP,
    level,
    badges,
    dailyGoal,
    weeklyStats,
    monthlyStats,
    getTodaysStats,
    getLevelProgress,
    getStreakInfo
  } = useProgressStore()
  const { user } = useAuthStore()
  const { text: t, isRTL } = useUIText()

  const [selectedPeriod, setSelectedPeriod] = useState<'week' | 'month' | 'all'>('week')
  const [selectedTab, setSelectedTab] = useState<'overview' | 'badges' | 'stats'>('overview')

  const todaysStats = getTodaysStats()
  const levelProgress = getLevelProgress()
  const streakInfo = getStreakInfo()

  const progressPercentage = (todaysStats.ayahsStudied / dailyGoal) * 100

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-50 to-primary-100 dark:from-gray-900 dark:to-gray-800 pb-20">
      <div className={`max-w-md mx-auto px-4 py-8 ${isRTL ? 'rtl-content' : 'ltr-content'}`}>
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center justify-between mb-8"
        >
          <button
            onClick={() => navigate('/')}
            className="p-2 rounded-lg bg-white dark:bg-gray-800 shadow-sm"
          >
            <span className="text-xl">←</span>
          </button>
          
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {t.yourProgress}
          </h1>
          
          <div className="w-10" /> {/* Spacer */}
        </motion.div>

        {/* User greeting */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="text-center mb-8"
        >
          <h2 className="text-lg text-gray-600 dark:text-gray-400">
            {user?.displayName || t.seekerOfKnowledge}
          </h2>
          <p className="text-sm text-gray-500 dark:text-gray-500">
            {t.level} {level} • {totalXP} {t.totalXP}
          </p>
        </motion.div>

        {/* Tab navigation */}
        <div className="flex bg-gray-100 dark:bg-gray-800 rounded-lg p-1 mb-6">
          {[
            { id: 'overview', label: t.overview, icon: '📊' },
            { id: 'badges', label: t.badges, icon: '🏆' },
            { id: 'stats', label: t.stats, icon: '📈' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setSelectedTab(tab.id as any)}
              className={`flex-1 flex items-center justify-center space-x-2 py-2 px-3 rounded-md text-sm font-medium transition-colors ${
                selectedTab === tab.id
                  ? 'bg-white dark:bg-gray-700 text-primary-700 dark:text-gold-400 shadow-sm'
                  : 'text-gray-600 dark:text-gray-400'
              }`}
            >
              <span>{tab.icon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>

        {/* Tab content */}
        <AnimatePresence mode="wait">
          {selectedTab === 'overview' && (
            <OverviewTab
              key="overview"
              streak={streak}
              level={level}
              totalXP={totalXP}
              todaysStats={todaysStats}
              dailyGoal={dailyGoal}
              progressPercentage={progressPercentage}
              levelProgress={levelProgress}
              streakInfo={streakInfo}
            />
          )}
          
          {selectedTab === 'badges' && (
            <BadgesTab
              key="badges"
              badges={badges}
            />
          )}
          
          {selectedTab === 'stats' && (
            <StatsTab
              key="stats"
              selectedPeriod={selectedPeriod}
              onPeriodChange={setSelectedPeriod}
              weeklyStats={weeklyStats}
              monthlyStats={monthlyStats}
              todaysStats={todaysStats}
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

// Overview tab component
const OverviewTab: React.FC<{
  streak: number
  level: number
  totalXP: number
  todaysStats: any
  dailyGoal: number
  progressPercentage: number
  levelProgress: any
  streakInfo: any
}> = ({ 
  streak, 
  level, 
  todaysStats,
  dailyGoal, 
  progressPercentage, 
  levelProgress, 
  streakInfo 
}) => {
  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      {/* Main stats cards */}
      <div className="grid grid-cols-2 gap-4">
        {/* Streak */}
        <div className="card p-4 text-center">
          <motion.div
            className="text-3xl mb-2"
            animate={streak > 0 ? {
              scale: [1, 1.2, 1],
              rotate: [0, -5, 5, 0]
            } : {}}
            transition={{
              duration: 2,
              repeat: streak > 0 ? Infinity : 0,
              repeatDelay: 3
            }}
          >
            🔥
          </motion.div>
          <p className="text-2xl font-bold text-primary-700 dark:text-gold-400">
            {streak}
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.dayStreak}</p>
          {streakInfo.isAtRisk && (
            <p className="text-xs text-orange-500 mt-1">
              ⚠️ {t.atRisk}
            </p>
          )}
        </div>

        {/* Level */}
        <div className="card p-4 text-center">
          <div className="text-3xl mb-2">⭐</div>
          <p className="text-2xl font-bold text-primary-700 dark:text-gold-400">
            {level}
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.level}</p>
        </div>
      </div>

      {/* Level progress */}
      <div className="card p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            {t.levelProgress}
          </h3>
          <span className="text-sm text-gray-600 dark:text-gray-400">
            {levelProgress.currentXP} / {levelProgress.xpNeeded} {t.totalXP}
          </span>
        </div>

        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3 mb-4 overflow-hidden">
          <motion.div
            className="h-full bg-gradient-to-r from-primary-500 to-primary-600 dark:from-gold-500 dark:to-gold-600 rounded-full"
            initial={{ width: 0 }}
            animate={{ width: `${levelProgress.percentage}%` }}
            transition={{ duration: 1, ease: "easeOut" }}
          />
        </div>

        <div className="flex justify-between text-sm text-gray-600 dark:text-gray-400">
          <span>{t.level} {level}</span>
          <span>{levelProgress.xpRemaining} {t.xpToNextLevel} {level + 1}</span>
        </div>
      </div>

      {/* Today's progress */}
      <div className="card p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            {t.todaysGoal}
          </h3>
          <span className="text-sm text-gray-600 dark:text-gray-400">
            {todaysStats.ayahsStudied} / {dailyGoal} {t.ayahsPerDay}
          </span>
        </div>

        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3 mb-4 overflow-hidden">
          <motion.div
            className="h-full bg-gradient-to-r from-green-500 to-green-600 rounded-full"
            initial={{ width: 0 }}
            animate={{ width: `${Math.min(progressPercentage, 100)}%` }}
            transition={{ duration: 1, ease: "easeOut" }}
          />
        </div>

        {progressPercentage >= 100 ? (
          <div className="text-center text-green-600 dark:text-green-400 font-medium">
            {t.alhamdulillahGoalComplete}
          </div>
        ) : (
          <div className="text-center text-gray-600 dark:text-gray-400">
            {dailyGoal - todaysStats.ayahsStudied} {t.moreAyahsToGoal}
          </div>
        )}
      </div>

      {/* Quick stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="card p-4 text-center">
          <div className="text-xl mb-1">📚</div>
          <p className="text-lg font-semibold text-gray-900 dark:text-white">
            {todaysStats.lessonsCompleted}
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.lessonsToday}</p>
        </div>

        <div className="card p-4 text-center">
          <div className="text-xl mb-1">⏱️</div>
          <p className="text-lg font-semibold text-gray-900 dark:text-white">
            {todaysStats.timeSpent} min
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.timeToday}</p>
        </div>
      </div>
    </motion.div>
  )
}

// Badges tab component
const BadgesTab: React.FC<{
  badges: any[]
}> = ({ badges }) => {
  const { text: t } = useUIText()
  
  const badgeCategories = [
    { id: 'streak', name: t.streakBadges, icon: '🔥' },
    { id: 'learning', name: t.learningBadges, icon: '📚' },
    { id: 'achievement', name: t.achievementBadges, icon: '🏆' },
    { id: 'special', name: t.specialBadges, icon: '✨' }
  ]

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      {badgeCategories.map((category) => {
        const categoryBadges = badges.filter(badge => badge.category === category.id)
        
        return (
          <div key={category.id} className="card p-6">
            <div className="flex items-center space-x-2 mb-4">
              <span className="text-xl">{category.icon}</span>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                {category.name}
              </h3>
              <span className="text-sm text-gray-500 dark:text-gray-400">
                ({categoryBadges.length})
              </span>
            </div>

            {categoryBadges.length > 0 ? (
              <div className="grid grid-cols-3 gap-3">
                {categoryBadges.map((badge, index) => (
                  <motion.div
                    key={badge.id}
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: index * 0.1 }}
                    className="text-center p-3 bg-gray-50 dark:bg-gray-700 rounded-lg"
                  >
                    <div className="text-2xl mb-1">{badge.icon}</div>
                    <p className="text-xs font-medium text-gray-900 dark:text-white">
                      {badge.name}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                      {new Date(badge.earnedAt).toLocaleDateString()}
                    </p>
                  </motion.div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                <p>{t.noBadgesYet}</p>
                <p className="text-sm mt-1">{t.keepLearningUnlockBadges}</p>
              </div>
            )}
          </div>
        )
      })}

      {/* Upcoming badges */}
      <div className="card p-6">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          🎯 {t.nextBadgeGoals}
        </h3>
        
        <div className="space-y-3">
          {[
            { name: '7-Day Streak', description: 'Study for 7 consecutive days', progress: 70 },
            { name: 'Night Owl', description: 'Study after 9 PM', progress: 30 },
            { name: 'Early Bird', description: 'Study before 7 AM', progress: 0 }
          ].map((goal, index) => (
            <div key={index} className="flex items-center justify-between">
              <div>
                <p className="font-medium text-gray-900 dark:text-white">{goal.name}</p>
                <p className="text-sm text-gray-600 dark:text-gray-400">{goal.description}</p>
              </div>
              <div className="text-right">
                <p className="text-sm font-medium text-primary-700 dark:text-gold-400">
                  {goal.progress}%
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </motion.div>
  )
}

// Stats tab component  
const StatsTab: React.FC<{
  selectedPeriod: 'week' | 'month' | 'all'
  onPeriodChange: (period: 'week' | 'month' | 'all') => void
  weeklyStats: any
  monthlyStats: any
  todaysStats: any
}> = ({ selectedPeriod, onPeriodChange, weeklyStats, monthlyStats }) => {
  const { text: t } = useUIText()
  
  const periods = [
    { id: 'week' as const, label: t.thisWeek },
    { id: 'month' as const, label: t.thisMonth },
    { id: 'all' as const, label: t.allTime }
  ]

  const currentStats = selectedPeriod === 'week' ? weeklyStats : monthlyStats

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -20 }}
      className="space-y-6"
    >
      {/* Period selector */}
      <div className="flex bg-gray-100 dark:bg-gray-800 rounded-lg p-1">
        {periods.map((period) => (
          <button
            key={period.id}
            onClick={() => onPeriodChange(period.id)}
            className={`flex-1 py-2 px-3 rounded-md text-sm font-medium transition-colors ${
              selectedPeriod === period.id
                ? 'bg-white dark:bg-gray-700 text-primary-700 dark:text-gold-400 shadow-sm'
                : 'text-gray-600 dark:text-gray-400'
            }`}
          >
            {period.label}
          </button>
        ))}
      </div>

      {/* Stats cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="card p-4 text-center">
          <div className="text-xl mb-1">📖</div>
          <p className="text-lg font-semibold text-gray-900 dark:text-white">
            {currentStats?.ayahsStudied || 0}
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.ayahsStudied}</p>
        </div>

        <div className="card p-4 text-center">
          <div className="text-xl mb-1">⏱️</div>
          <p className="text-lg font-semibold text-gray-900 dark:text-white">
            {Math.floor((currentStats?.timeSpent || 0) / 60)}h {(currentStats?.timeSpent || 0) % 60}m
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.timeSpent}</p>
        </div>

        <div className="card p-4 text-center">
          <div className="text-xl mb-1">🎯</div>
          <p className="text-lg font-semibold text-gray-900 dark:text-white">
            {currentStats?.lessonsCompleted || 0}
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.lessonsDone}</p>
        </div>

        <div className="card p-4 text-center">
          <div className="text-xl mb-1">⭐</div>
          <p className="text-lg font-semibold text-gray-900 dark:text-white">
            {currentStats?.xpEarned || 0}
          </p>
          <p className="text-sm text-gray-600 dark:text-gray-400">{t.xpEarned}</p>
        </div>
      </div>

      {/* Activity chart placeholder */}
      <div className="card p-6">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          {t.dailyActivity}
        </h3>
        
        <div className="grid grid-cols-7 gap-2 mb-4">
          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, index) => (
            <div key={index} className="text-center text-sm font-medium text-gray-600 dark:text-gray-400">
              {day}
            </div>
          ))}
        </div>
        
        <div className="grid grid-cols-7 gap-2">
          {Array.from({ length: 7 }, (_, index) => {
            const intensity = Math.random() // Replace with actual data
            return (
              <div
                key={index}
                className={`aspect-square rounded ${
                  intensity > 0.7
                    ? 'bg-green-500'
                    : intensity > 0.4
                    ? 'bg-green-300'
                    : intensity > 0.1
                    ? 'bg-green-100'
                    : 'bg-gray-100 dark:bg-gray-700'
                }`}
              />
            )
          })}
        </div>
        
        <div className="flex items-center justify-between mt-4 text-sm text-gray-600 dark:text-gray-400">
          <span>{t.lessActivity}</span>
          <div className="flex space-x-1">
            <div className="w-3 h-3 bg-gray-100 dark:bg-gray-700 rounded" />
            <div className="w-3 h-3 bg-green-100 rounded" />
            <div className="w-3 h-3 bg-green-300 rounded" />
            <div className="w-3 h-3 bg-green-500 rounded" />
          </div>
          <span>{t.moreActivity}</span>
        </div>
      </div>

      {/* Achievements summary */}
      <div className="card p-6">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          {t.recentAchievements}
        </h3>
        
        <div className="space-y-3">
          {[
            { text: 'Completed 5 consecutive days of study', date: t.daysAgo, icon: '🔥' },
            { text: 'Reached Level 3', date: t.weekAgo, icon: '⭐' },
            { text: 'First lesson completed', date: t.weeksAgo, icon: '🎯' }
          ].map((achievement, index) => (
            <div key={index} className="flex items-center space-x-3">
              <span className="text-xl">{achievement.icon}</span>
              <div className="flex-1">
                <p className="text-sm font-medium text-gray-900 dark:text-white">
                  {achievement.text}
                </p>
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  {achievement.date}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </motion.div>
  )
}

export default ProgressPage